function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  fraudUrl: 'https://httpbin.org/post',
  level1Url: 'https://httpbin.org/post',
  level2Url: 'https://httpbin.org/post',
  processUrl: 'https://httpbin.org/post',
  timeoutMs: 15000,
  // Risk thresholds
  policies: {
    autoApproveBelow: 50,          // risk score
    level1Below: 70,
    // above 70 → requires Level 2
    highRiskReasons: ['chargeback', 'friendly_fraud', 'duplicate', 'unauthorized'],
    highRiskAmount: 500
  },
  allowSimulation: true
};

const hook = ref('Webhook - Refund Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const refundId = String(body.refundId || body.id || ('REF-' + Date.now())).trim();
const paymentId = String(body.paymentId || body.originalPaymentId || '').trim();
const amount = Number(body.amount || body.value || 0);
const currency = String(body.currency || 'USD').toUpperCase();
const reason = String(body.reason || body.refundReason || 'customer_request').toLowerCase();
const customerId = String(body.customerId || body.customer_id || '').trim();
const email = String(body.email || body.customerEmail || '').trim();
const daysSincePurchase = Number(body.daysSincePurchase || body.ageDays || 0);
const previousRefunds = Number(body.previousRefunds || 0);

if (!paymentId) errors.push('paymentId is required');
if (!Number.isFinite(amount) || amount <= 0) errors.push('amount must be a positive number');
if (!customerId) errors.push('customerId is required');

const valid = errors.length === 0;

// Calculate internal fraud risk score (0-100)
let riskScore = 15;
if (amount >= CONFIG.policies.highRiskAmount) riskScore += 25;
if (CONFIG.policies.highRiskReasons.includes(reason)) riskScore += 30;
if (daysSincePurchase > 60) riskScore += 15;
if (previousRefunds >= 3) riskScore += 20;
if (previousRefunds >= 5) riskScore += 15;
riskScore = Math.min(riskScore, 100);

let requiredLevels = [];
let autoApproved = false;

if (riskScore < CONFIG.policies.autoApproveBelow && amount < 100) {
  autoApproved = true;
  requiredLevels = [];
} else {
  requiredLevels.push(1);
  if (riskScore >= CONFIG.policies.level1Below || amount >= CONFIG.policies.highRiskAmount) {
    requiredLevels.push(2);
  }
}

let fraudUrl = CONFIG.fraudUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  fraudUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    request: {
      refundId,
      paymentId,
      amount,
      currency,
      reason,
      customerId,
      email,
      daysSincePurchase,
      previousRefunds
    },
    evaluation: {
      riskScore,
      requiredLevels,
      autoApproved,
      maxLevel: requiredLevels.length ? Math.max(...requiredLevels) : 0
    },
    urls: {
      fraud: fraudUrl,
      level1: CONFIG.level1Url,
      level2: CONFIG.level2Url,
      process: CONFIG.processUrl
    },
    decisions: {}
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const ctx = ref('Code - Validate & Score Fraud Risk');
const fraudRes = ref('HTTP Request - Fraud Service Check') || {};
const l1Res = ref('HTTP Request - Level 1 Approver') || {};
const l2Res = ref('HTTP Request - Level 2 Approver') || {};
const processRes = ref('HTTP Request - Process Refund / Reject') || {};

function statusOf(res) {
  return Number(res.statusCode) || 0;
}

const fraudOk = statusOf(fraudRes) >= 200 && statusOf(fraudRes) < 300;
const needsL1 = (ctx.evaluation.requiredLevels || []).includes(1);
const needsL2 = (ctx.evaluation.requiredLevels || []).includes(2);

const l1Approved = !needsL1 || (statusOf(l1Res) >= 200 && statusOf(l1Res) < 300);
const l2Approved = !needsL2 || (statusOf(l2Res) >= 200 && statusOf(l2Res) < 300);
const processOk = statusOf(processRes) >= 200 && statusOf(processRes) < 300;

let finalStatus = 'approved';
const rejectedBy = [];

if (ctx.evaluation.autoApproved) {
  finalStatus = 'auto_approved';
} else {
  if (!fraudOk) {
    finalStatus = 'rejected';
    rejectedBy.push('fraud_service');
  }
  if (needsL1 && !l1Approved) {
    finalStatus = 'rejected';
    rejectedBy.push('level1');
  }
  if (needsL2 && !l2Approved) {
    finalStatus = 'rejected';
    rejectedBy.push('level2');
  }
  if (finalStatus === 'approved' && !processOk) {
    finalStatus = 'approved_but_process_failed';
  }
}

const decisions = {
  fraud: {
    required: true,
    passed: fraudOk,
    status: statusOf(fraudRes),
    decidedAt: new Date().toISOString()
  },
  level1: {
    required: needsL1,
    approved: l1Approved,
    status: statusOf(l1Res),
    decidedAt: new Date().toISOString()
  },
  level2: {
    required: needsL2,
    approved: l2Approved,
    status: statusOf(l2Res),
    decidedAt: new Date().toISOString()
  },
  process: {
    success: processOk,
    status: statusOf(processRes),
    decidedAt: new Date().toISOString()
  }
};

const body = {
  refundId: ctx.request.refundId,
  request: ctx.request,
  evaluation: {
    riskScore: ctx.evaluation.riskScore,
    requiredLevels: ctx.evaluation.requiredLevels,
    autoApproved: ctx.evaluation.autoApproved
  },
  decisions,
  final: {
    status: finalStatus,
    rejectedBy,
    decidedAt: new Date().toISOString()
  }
};

const httpStatus = (finalStatus === 'approved' || finalStatus === 'auto_approved') ? 200 : 403;

return [{
  json: {
    httpStatus,
    body,
    refundId: ctx.request.refundId
  }
}];
